const storageKey = "notepad-content";
const timestampKey = "notepad-lastSaved";

export function load() {
    return localStorage.getItem(storageKey);
}

export function save(content) {
    localStorage.setItem(storageKey, content);
    const now = new Date().toLocaleTimeString([], { hour12: false });
    localStorage.setItem(timestampKey, now);
    return now;
}

export function clear() {
    localStorage.removeItem(storageKey);
    localStorage.removeItem(timestampKey);
}

let beforeUnloadHandler = null;

export function enableUnloadPrompt() {
    if (!beforeUnloadHandler) {
        beforeUnloadHandler = (e) => {
            e.preventDefault();
        };
        window.addEventListener("beforeunload", beforeUnloadHandler);
    }
}

export function disableUnloadPrompt() {
    if (beforeUnloadHandler) {
        window.removeEventListener("beforeunload", beforeUnloadHandler);
        beforeUnloadHandler = null;
    }
}

@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<div class="mb-3">
    <textarea class="form-control" rows="10" @bind="content" @bind:event="oninput" placeholder="Type your notes here..."></textarea>
</div>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string? lastSavedAt;
    private string lastSavedContent = string.Empty;
    private IJSObjectReference? module;
    private System.Threading.Timer? autoSaveTimer;

    private bool HasUnsavedChanges => content != lastSavedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", $"./{Assets["Components/Pages/Notepad.razor.js"]}");

            var saved = await module.InvokeAsync<string?>("load");
            if (saved is not null)
            {
                content = saved;
                lastSavedContent = saved;
                lastSavedAt = "restored from previous session";
                StateHasChanged();
            }

            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSave),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private async Task AutoSave()
    {
        if (module is null || !HasUnsavedChanges) return;
        await PerformSave();
        StateHasChanged();
    }

    private async Task SaveNow()
    {
        if (module is null) return;
        await PerformSave();
    }

    private async Task PerformSave()
    {
        if (module is null) return;
        lastSavedAt = await module.InvokeAsync<string>("save", content);
        lastSavedContent = content;
        await module.InvokeVoidAsync("disableUnloadPrompt");
    }

    private async Task Clear()
    {
        if (module is null) return;
        content = string.Empty;
        lastSavedContent = string.Empty;
        lastSavedAt = null;
        await module.InvokeVoidAsync("clear");
        await module.InvokeVoidAsync("disableUnloadPrompt");
    }

    protected override async Task OnAfterRenderAsync_UpdateUnloadPrompt()
    {
        // This is handled via the overridden method below
    }

    // We track dirty state after each render to toggle the beforeunload prompt
    private bool previousHasUnsavedChanges;

    protected override void OnInitialized()
    {
        previousHasUnsavedChanges = false;
    }

    // Not ideal to use OnAfterRender for this, so let's integrate into content change instead.

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }

        if (module is not null)
        {
            await module.InvokeVoidAsync("disableUnloadPrompt");
            await module.DisposeAsync();
        }
    }
}

